<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
class CcsStaffNotifications {
 public function items($user): array {
  $admin=app(CcsAdministration::class);$p=$admin->preferences($user->id);$items=[];
  if($p['notify_jobs'])foreach(DB::table('repair_jobs as j')->join('vehicles as v','v.id','=','j.vehicle_id')->join('customers as c','c.id','=','v.customer_id')->whereNull('j.deleted_at')->whereNull('v.deleted_at')->whereNull('c.deleted_at')->where('j.created_at','>=',now()->subDays(7))->orderByDesc('j.id')->limit(20)->get(['j.id','j.job_number','j.created_at','v.registration_number']) as $j)$items[]=['key'=>'job:'.$j->id,'type'=>'jobs','title'=>'New repair job','text'=>$j->job_number.' · '.$j->registration_number,'url'=>route('ccs.jobs',['job_id'=>$j->id]),'date'=>$j->created_at];
  if($p['notify_stock']&&$admin->can($user,'ccs.stock'))foreach(DB::table('inventory_items')->where('active',true)->whereColumn('quantity_on_hand','<=','reorder_level')->orderBy('quantity_on_hand')->limit(20)->get() as $part)$items[]=['key'=>'stock:'.$part->id.':'.strtotime($part->updated_at??'1970-01-01'),'type'=>'stock','title'=>$part->quantity_on_hand<=0?'Out of stock':'Low stock','text'=>$part->name.' · '.$part->quantity_on_hand.' available','url'=>route('ccs.stock',['q'=>$part->sku]),'date'=>$part->updated_at];
  if($p['notify_warranty']&&$admin->can($user,'ccs.warranties'))foreach(DB::table('warranties as w')->join('warranty_rules as wr','wr.id','=','w.warranty_rule_id')->where('wr.approved_by_owner',true)->where('wr.active',true)->join('repair_jobs as j','j.id','=','w.repair_job_id')->join('vehicles as v','v.id','=','j.vehicle_id')->join('customers as c','c.id','=','v.customer_id')->whereNull('c.deleted_at')->whereNull('v.deleted_at')->whereNull('j.deleted_at')->whereBetween('w.expires_on',[today()->toDateString(),today()->addDays(10)->toDateString()])->orderBy('w.expires_on')->limit(20)->get(['w.id','w.expires_on','w.terms_snapshot','v.customer_id','v.registration_number']) as $w){$s=json_decode($w->terms_snapshot,true)??[];if(($s['provisional']??true)!==false)continue;$items[]=['key'=>'warranty:'.$w->id.':'.$w->expires_on,'type'=>'warranty','title'=>'Warranty end date approaching','text'=>sprintf('CCS-W%06d',$w->id).' · '.$w->registration_number.' · '.$w->expires_on,'url'=>route('ccs.warranties',['customer_id'=>$w->customer_id]),'date'=>$w->expires_on];}
  if($p['notify_claims'])foreach(DB::table('warranty_claims as cl')->join('warranties as w','w.id','=','cl.warranty_id')->join('repair_jobs as j','j.id','=','w.repair_job_id')->join('vehicles as v','v.id','=','j.vehicle_id')->join('customers as c','c.id','=','v.customer_id')->whereNull('j.deleted_at')->whereNull('v.deleted_at')->whereNull('c.deleted_at')->whereIn('cl.status',['pending','approved'])->orderByDesc('cl.id')->limit(20)->get(['cl.id','cl.status','cl.updated_at','v.registration_number']) as $c)$items[]=['key'=>'claim:'.$c->id.':'.strtotime($c->updated_at),'type'=>'claims','title'=>'Warranty claim needs attention','text'=>'Claim #'.$c->id.' · '.$c->registration_number.' · '.$c->status,'url'=>route('ccs.claims.index',['q'=>$c->registration_number]),'date'=>$c->updated_at];
  // CCS_WEBSITE_NOTIFICATIONS
  $items=array_merge($items,app(\App\Services\CcsWebsiteNotifications::class)->items($user));
  $read=DB::table('ccs_notification_reads')->where('user_id',$user->id)->whereIn('notification_key',array_column($items,'key'))->pluck('notification_key')->all();foreach($items as &$item)$item['read']=in_array($item['key'],$read,true);unset($item);return $items;
 }
}
